def process(msa_html) -> pd.DataFrame:
    import pandas as pd, re, ast

    def norm(s: str) -> str:
        s = s.lower()
        s = re.sub(r"\bmetropolitan statistical area\b|\bmsa\b", "", s)
        s = re.sub(r"\(.*?\)", "", s)
        s = s.replace('&', 'and')
        s = re.sub(r"[^a-z0-9, ]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    rows = []
    for _, r in msa_html.iterrows():
        try:
            cells = ast.literal_eval(r['cells']) if isinstance(r['cells'], str) else r['cells']
        except Exception:
            cells = r['cells']
        if not isinstance(cells, (list, tuple)) or len(cells) < 2:
            continue
        # Heuristic: rows that look like metro area population tables often have first cell as name, and multiple year columns.
        # We'll keep rows where first cell contains a comma and at least two numeric-like cells.
        name = str(cells[0]).strip()
        if ',' not in name:
            continue
        nums = []
        for c in cells[1:]:
            c2 = str(c)
            c2 = c2.replace(',', '')
            if re.fullmatch(r"-?\d+(?:\.\d+)?", c2):
                nums.append(float(c2))
        if len(nums) < 2:
            continue
        rows.append({
            'raw_name': name,
            'norm_name': norm(name),
            'cells': cells,
            'n_numeric': len(nums)
        })
    return pd.DataFrame(rows)

def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    paths = glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*')
    dfs = []
    for p in paths:
        if os.path.isdir(p):
            continue
        try:
            df = pd.read_csv(p)
        except Exception:
            df = pd.read_csv(p, encoding='latin-1')
        df['__source_file'] = os.path.basename(p)
        dfs.append(df)
    if not dfs:
        return pd.DataFrame()
    out = pd.concat(dfs, ignore_index=True)
    return out

import pandas as pd
import re

def process(it_csvs: pd.DataFrame) -> pd.DataFrame:
    df = it_csvs.rename(columns={
        'Metropolitan Areas: Identity Theft Reports': 'msa_raw',
        'Unnamed: 1': 'value_raw'
    }).copy()

    def is_data_row(msa):
        if pd.isna(msa):
            return False
        s = str(msa).strip()
        if not s:
            return False
        bad_prefixes = [
            'Metropolitan Area',
            'Metropolitan Areas are defined',
            'Source:'
        ]
        return not any(s.startswith(p) for p in bad_prefixes)

    df = df[df['msa_raw'].apply(is_data_row)].copy()

    # parse numeric
    def to_int(x):
        if pd.isna(x):
            return None
        s = str(x)
        s = re.sub(r'[^0-9]', '', s)
        return int(s) if s else None

    df['reports'] = df['value_raw'].apply(to_int)
    df = df[df['reports'].notna()].copy()

    # If duplicates across states, keep max reports (same MSA can appear multiple times in multi-state files)
    df['msa_raw'] = df['msa_raw'].astype(str).str.strip()
    df = df.groupby('msa_raw', as_index=False)['reports'].max()

    return df.sort_values('reports', ascending=False).reset_index(drop=True)
